insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'gk_ss_v1'
from (values
('113.11.c.1.A',2,'Which day do we remember soldiers who served our country?','["Veterans Day", "Valentine''s Day", "Groundhog Day", "Halloween"]'::jsonb,0,'Veterans Day honors people who served in the military.','original'),
('113.11.c.1.A',2,'On which holiday do we celebrate the birthday of our country?','["Earth Day", "Independence Day", "Pi Day", "April Fools'' Day"]'::jsonb,1,'Independence Day is on July 4.','original'),
('113.11.c.1.A',3,'Which day honors our presidents?','["Pajama Day", "Pizza Day", "Presidents'' Day", "Leap Day"]'::jsonb,2,'Presidents'' Day honors leaders of our nation.','original'),
('113.11.c.1.B',2,'Which is something people may see on Independence Day?','["snowmen", "pumpkins", "Easter eggs", "fireworks"]'::jsonb,3,'Fireworks are a July 4 custom.','original'),
('113.11.c.1.B',2,'What do many towns hold on Independence Day?','["a parade", "a snow day", "a bake-off for turkeys", "a pumpkin patch"]'::jsonb,0,'Parades are a national holiday custom.','original'),
('113.11.c.2',3,'Who was the first President of the United States?','["Mickey Mouse", "George Washington", "Santa Claus", "Taylor Swift"]'::jsonb,1,'George Washington led the new nation.','original'),
('113.11.c.2',2,'Who is known for helping lead Texas, as a hero at the Alamo?','["Superman", "Paul Bunyan", "Davy Crockett", "Cinderella"]'::jsonb,2,'Davy Crockett was at the Alamo.','original'),
('113.11.c.2',2,'Which person helped enslaved people find freedom and is honored in American history?','["Snow White", "Pinocchio", "Peter Pan", "Harriet Tubman"]'::jsonb,3,'Harriet Tubman helped many reach freedom.','original'),
('113.11.c.3.A',3,'A cat is hiding below the chair. Which word tells where the cat is?','["under", "over", "far", "near"]'::jsonb,0,'Under means below.','original'),
('113.11.c.3.A',2,'Which word tells that something is close by?','["over", "near", "under", "far"]'::jsonb,1,'Near means close.','original'),
('113.11.c.3.A',2,'A bird is high above your head. Which word fits?','["beneath", "under", "over", "inside"]'::jsonb,2,'Over means above.','original'),
('113.11.c.3.A',3,'You write with your right hand. Which word names your other hand?','["down", "far", "up", "left"]'::jsonb,3,'The other hand is the left.','original'),
('113.11.c.3.B',2,'Which place on a school campus is where you borrow books?','["library", "cafeteria", "nurse''s office", "gym"]'::jsonb,0,'The library has books.','original'),
('113.11.c.3.B',2,'Where do students usually eat lunch at school?','["library", "cafeteria", "office", "playground"]'::jsonb,1,'The cafeteria serves lunch.','original'),
('113.11.c.3.B',3,'The playground is near the gym. Which is true?','["they are in different states", "they are far away", "they are close to each other", "one is underwater"]'::jsonb,2,'Near means close.','original'),
('113.11.c.3.C',2,'Which tool is a round model of the Earth?','["ruler", "calendar", "clock", "globe"]'::jsonb,3,'A globe shows the whole Earth.','original'),
('113.11.c.3.C',2,'Which tool shows where places are on flat paper?','["map", "button", "brush", "spoon"]'::jsonb,0,'Maps show locations.','original'),
('113.11.c.4.A',3,'Which is a body of water?','["desert", "lake", "hill", "mountain"]'::jsonb,1,'A lake is water.','original'),
('113.11.c.4.A',2,'Which is a landform?','["river", "ocean", "mountain", "rain"]'::jsonb,2,'A mountain is land.','original'),
('113.11.c.4.B',3,'People in very cold places often wear...','["swim shorts", "sun hats", "sandals", "warm coats"]'::jsonb,3,'Weather affects clothing.','original'),
('113.11.c.4.B',2,'People who live where it snows a lot need what kind of shelter?','["a warm, sturdy house", "an open field", "a sandcastle", "a paper boat"]'::jsonb,0,'Shelter protects from weather.','original'),
('113.11.c.5.A',2,'Which is a basic human need?','["a video game", "food", "a toy", "a new bike"]'::jsonb,1,'People need food to live.','original'),
('113.11.c.5.A',3,'Which is something every person needs to stay safe and warm?','["a sticker", "a balloon", "shelter", "a skateboard"]'::jsonb,2,'Shelter protects people.','original'),
('113.11.c.5.A',2,'Which is a basic need for the body when it is cold outside?','["a book of jokes", "a stuffed animal", "a trophy", "clothing"]'::jsonb,3,'Clothes keep people warm.','original'),
('113.11.c.5.B',2,'Which is a want, not a need?','["a toy", "water", "a place to sleep", "food"]'::jsonb,0,'A toy is nice to have but not needed to live.','original'),
('113.11.c.5.B',3,'Which is a need, not a want?','["a game", "water", "candy", "a sticker"]'::jsonb,1,'People need water.','original'),
('113.11.c.5.C',2,'How can a family get food?','["find it in a closet of toys", "ask the clouds", "buy it at a store", "wait for it to fall from the moon"]'::jsonb,2,'Families get food by buying or growing it.','original'),
('113.11.c.5.C',2,'How can a person meet the need for clothing?','["plant a clock", "eat a book", "paint a rock", "buy or wear clothes"]'::jsonb,3,'Clothes can be bought or made.','original'),
('113.11.c.6.A',3,'Which person has a job in the community and puts out fires?','["firefighter", "clown", "painter of birthday signs", "toy maker"]'::jsonb,0,'Firefighters fight fires.','original'),
('113.11.c.6.A',2,'Which job is done at school?','["astronaut", "teacher", "lifeguard", "pilot"]'::jsonb,1,'Teachers work at schools.','original'),
('113.11.c.6.A',2,'Which is a job a person might do at home?','["driving a bus", "flying a plane", "cooking dinner", "running a store"]'::jsonb,2,'Cooking is a job at home.','original'),
('113.11.c.6.B',3,'Why do people have jobs?','["to avoid all food", "to forget school", "to get lost", "to earn money for what they need"]'::jsonb,3,'Jobs earn money for needs.','original'),
('113.11.c.6.B',2,'A person works as a baker. What do they help others do?','["get bread and treats", "plant forests", "build bridges", "travel to space"]'::jsonb,0,'A baker makes food.','original'),
('113.11.c.7.A',2,'Why do we have rules?','["to make people lost", "to keep us safe and fair", "to make everyone sad", "to hide toys"]'::jsonb,1,'Rules help us stay safe.','original'),
('113.11.c.7.A',3,'Which is a good reason for a rule about walking in the hall?','["to make hallways loud", "to knock things over", "to keep everyone safe", "to run races"]'::jsonb,2,'Walking keeps people from getting hurt.','original'),
('113.11.c.7.B',2,'Which rule keeps you safe at home?','["Put your hand in the fire.", "Throw toys on the stairs.", "Run in the kitchen.", "Look both ways before crossing the street."]'::jsonb,3,'Looking both ways is a safety rule.','original'),
('113.11.c.7.B',2,'Which rule helps order in the classroom?','["Raise your hand to speak.", "Leave trash on the floor.", "Shout across the room.", "Take things without asking."]'::jsonb,0,'Raising a hand gives everyone a turn.','original'),
('113.11.c.8.A',3,'Who is an authority figure at school?','["a cartoon dog", "principal", "a pet fish", "a baby doll"]'::jsonb,1,'The principal is in charge at school.','original'),
('113.11.c.8.A',2,'Who is an authority figure in the community who helps keep people safe?','["balloon seller", "puppet", "police officer", "toy store clown"]'::jsonb,2,'Police officers help keep order.','original'),
('113.11.c.8.A',2,'Who is an authority figure at home?','["a pillow", "a teddy bear", "a toy car", "a parent"]'::jsonb,3,'Parents guide children at home.','original'),
('113.11.c.8.B',3,'How does a crossing guard help enforce rules?','["helps people cross when it is safe", "breaks the rules", "plays tag", "makes everyone go anywhere"]'::jsonb,0,'Crossing guards keep people safe.','original'),
('113.11.c.8.B',2,'If a student breaks a classroom rule, what might the teacher do?','["buy them a pony", "remind them of the rule", "give them a rocket", "move the school"]'::jsonb,1,'Teachers remind and guide.','original'),
('113.11.c.9.A',2,'Which flag has stars and stripes?','["Texas flag", "a flag with a lone star only", "United States flag", "a pirate flag"]'::jsonb,2,'The U.S. flag has 50 stars and 13 stripes.','original'),
('113.11.c.9.A',3,'Which flag has one big star?','["United States flag", "a flag with no colors", "a flag with 50 stars", "Texas flag"]'::jsonb,3,'The Texas flag has one star.','original'),
('113.11.c.9.B',2,'What do we say each day to show respect for our country''s flag?','["the Pledge of Allegiance", "a bedtime lullaby", "a happy birthday song", "a lunch order"]'::jsonb,0,'The pledge honors the flag.','original'),
('113.11.c.9.B',2,'When we say the Pledge of Allegiance, we usually...','["hide under the desk", "stand and face the flag", "do a cartwheel", "run outside"]'::jsonb,1,'We show respect by standing.','original'),
('113.11.c.9.C',3,'Your class cannot decide between two games. What is a fair way to choose?','["fight", "leave", "vote", "yell"]'::jsonb,2,'Voting lets everyone have a say.','original'),
('113.11.c.9.C',2,'When the class votes, which choice wins?','["the one with the fewest votes", "the one no one picked", "the one the teacher dislikes", "the one with the most votes"]'::jsonb,3,'The most votes win.','original'),
('113.11.c.10',2,'Which is a way people can be different?','["their favorite foods", "they all think the same thoughts", "they are all the same", "they all have the same name"]'::jsonb,0,'Likes can differ.','original'),
('113.11.c.10',3,'Which is a way people can be alike?','["they all wear identical socks", "they all need food", "they all have the same fingerprints", "they all speak every language"]'::jsonb,1,'All people need food.','original'),
('113.11.c.11.A',2,'Which is a family tradition?','["sleeping in a car", "forgetting a holiday", "baking a special cake each birthday", "losing a shoe"]'::jsonb,2,'Traditions are repeated customs.','original'),
('113.11.c.11.A',2,'Why are family traditions important?','["they make people sick", "they stop people from talking", "they cause trouble", "they bring family together"]'::jsonb,3,'Traditions create bonds.','original'),
('113.11.c.11.B',3,'One family eats tamales at holidays. Another eats pie. This shows...','["traditions can be different", "food is not needed", "no one has traditions", "everyone has the same tradition"]'::jsonb,0,'Families have different customs.','original'),
('113.11.c.12.A',2,'Which is technology used at school?','["pinecone", "computer", "leaf", "rock"]'::jsonb,1,'Computers are technology.','original'),
('113.11.c.12.A',2,'Which is technology used at home?','["cloud", "tree", "telephone", "bird"]'::jsonb,2,'A phone is a tool people made.','original'),
('113.11.c.12.B',3,'How does a phone help people?','["it teaches them to fly", "it helps them grow tall", "it makes them invisible", "they can talk to someone far away"]'::jsonb,3,'Phones connect people.','original'),
('113.11.c.12.B',2,'How does a washing machine help families?','["it cleans clothes", "it plants flowers", "it cooks dinner", "it paints the wall"]'::jsonb,0,'Machines save work.','original'),
('113.11.c.12.C',2,'Without electric lights, how might your evenings be different?','["it would be hotter", "it would be darker", "it would be louder", "it would be brighter"]'::jsonb,1,'Lights make dark places bright.','original'),
('113.11.c.13.A',3,'Which is a fact?','["The sun is the best color.", "The sun is angry.", "The sun gives us light.", "The sun likes cake."]'::jsonb,2,'A fact can be shown to be true.','original'),
('113.11.c.13.B',2,'Which is a historical source that shows how people lived long ago?','["a cookie", "a toy shop", "a new cartoon", "an old photograph"]'::jsonb,3,'Photos show the past.','original'),
('113.11.c.13.B',2,'A very old tool found in the ground is called a(n)...','["artifact", "cartoon", "joke", "lunchbox"]'::jsonb,0,'Artifacts are objects from the past.','original'),
('113.11.c.13.D',3,'You put pictures of fruits in one group and pictures of animals in another. This is...','["hiding", "categorizing", "erasing", "spilling"]'::jsonb,1,'Categorizing sorts things.','original'),
('113.11.c.13.D',2,'Which shows putting events in order?','["apple, shoe, cloud", "up, down, left", "first, next, last", "blue, green, red"]'::jsonb,2,'Sequence shows order.','original'),
('113.11.c.14.A',2,'Which order is right for a plant growing?','["sprout, plant, seed", "plant, seed, sprout", "plant, sprout, seed", "seed, sprout, plant"]'::jsonb,3,'A seed grows into a sprout and then a plant.','original'),
('113.11.c.14.B',3,'Which word tells what happens after today?','["tomorrow", "yesterday", "first", "before"]'::jsonb,0,'Tomorrow is the next day.','original'),
('113.11.c.14.B',2,'Which word tells what happened the day before today?','["last", "yesterday", "tomorrow", "next"]'::jsonb,1,'Yesterday is the day before.','original'),
('113.11.c.14.B',2,'Which word names the event that comes at the very start of a sequence?','["next", "after", "first", "last"]'::jsonb,2,'First begins the list.','original'),
('113.11.c.14.D',3,'What does a map picture show?','["what you hear", "what you ate", "how you feel", "where places are"]'::jsonb,3,'Maps show locations.','original'),
('113.11.c.14.D',2,'A picture of your classroom shows your desk next to the window. What does it tell you?','["where things are", "what time it is", "what you will eat", "who won a game"]'::jsonb,0,'Pictures show places.','original'),
('113.11.c.15.A',2,'The class wants to pick a new classroom pet. How can they choose fairly?','["toss the pets out", "take a vote", "let one person decide without asking", "flip over the desk"]'::jsonb,1,'Voting is democratic.','original'),
('113.11.c.15.B',3,'A student loses a library book. What is the first step in solving a problem?','["throw out all books", "blame a friend", "find out what the problem is", "ignore it"]'::jsonb,2,'First, identify the problem.','original'),
('113.11.c.15.B',2,'After you list choices to fix a problem, what should you do next?','["hide the list", "pick the choice with no thought", "forget them", "think about the good and bad of each"]'::jsonb,3,'Compare advantages and disadvantages.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
